def classify_triangle_by_sides(p1, p2, p3):
    def square_distance(a, b):
        return (a[0] - b[0])**2 + (a[1] - b[1])**2
    d1 = square_distance(p1, p2)
    d2 = square_distance(p2, p3)
    d3 = square_distance(p3, p1)
    if d1 == d2 == d3:
        return 'equilateral'
    elif d1 == d2 or d2 == d3 or d1 == d3:
        return 'isosceles'
    else:
