def is_convex_polygon(points):
        p = points + [points[0]] + [points[1]]
        for i in range(2, len(points) + 2):
            v1 = (p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1])
            v2 = (p[i - 1][0] - p[i - 2][0], p[i - 1][1] - p[i - 2][1])
            if cross(v1, v2) == 0:
