from typing import List, Tuple

def count_points_in_rectangle(points: List[Tuple[float, float]], rect: Tuple[float, float, float, float]) -> int:
    x1, y1, x2, y2 = rect
    return sum(1 for x, y in points if x1 <= x <= x2 and y1 <= y <= y2)
```

