def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    visited = set(requests)
    if direction == 1:
        stop = start_floor
        while stop <= top_floor:
            if stop in visited:
                yield stop
            stop += 1
        if top_floor in visited:
            yield top_floor
    else:  # direction == -1
        stop = start_floor
        while stop >= 1:
            if stop in visited:
                yield stop
            stop -= 1
        if 1 in visited:
            yield 1
    return list(yielding_block())
```

