def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    total_a = sum(durations_a)
    total_b = sum(durations_b)

    def phase(ticks, light_length):
        while ticks >= light_length:
            ticks -= light_length
        if ticks < light_length:
            return ticks
        raise ValueError("unexpected tick count")
    def light_color(ticks, light_length):
        mod = phase(ticks, light_length)
        if mod < light_length[0]:
            return 'RED'
        if mod < light_length[0] + light_length[1]:
            return 'GREEN'
        if mod < light_length[0] + light_length[1] + light_length[2]:
            return 'YELLOW'
        raise ValueError("unexpected tick count")
    def green_ticks_from_period(period, light_length):
        green_start = light_length[0]
        green_end = green_start + light_length[1]
        if green_end <= period:
            return green_end - green_start
        elif green_start > period:
            return 0
        else:
            return period - green_start
    sync_period = total_a * total_b
    factor_a = sync_period // total_a
    factor_b = sync_period // total_b
    safe_ticks = n_ticks
    full_cycles = safe_ticks // sync_period
    full_cycle_count = full_cycles * green_ticks_from_period(sync_period, durations_a) * green_ticks_from_period(sync_period, durations_b)
    remaining_ticks = safe_ticks % sync_period
    for t in range(remaining_ticks):
        hint_a = t % total_a
        hint_b = t % total_b
        if light_color(hint_a, durations_a) == 'GREEN' and light_color(hint_b, durations_b) == 'GREEN':
            full_cycle_count += 1
    return full_cycle_count
```

