def is_point_on_segment(p, a, b):
    if a == b:
        return p == a
    x, y = p
    ax, ay = a
    bx, by = b
    # Line from a to b is x = ax + t*(bx - ax), y = ay + t*(by - ay); we solve for t
    # Plug into parametric form, t has to lie between 0 and 1 inclusive, and the y position at that t has to match exactly
    if bx != ax:
        t = (x - ax) / (bx - ax)
