def is_square(p1, p2, p3, p4):
    from itertools import combinations, permutations
    points = [p1, p2, p3, p4]

    def squared_distance(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    dists = [squared_distance(*pair) for pair in combinations(points, 2)]
    dists.sort()

    def check(a, b, c, d):
        # Contains four equal sides and two equal diagonals
        return (a == b and a == c and a == d and a != e and e == f)

    # Try all 8 point orderings that can arise from drawing a square as the closing point
    for i in range(4):
        for j in range(4):
            if j != i:
                for perm in permutations([0, 1, 2, 3]):
                    if perm[2] == i or perm[3] == j:
                        continue
                    a, b, c, d = dists[perm]
                    if check(a, b, c, d):
                        return True
    return False
```

