class FloodState:
    cells = None
    next_cell = None
    capacity = None

def flood_fill(grid, sr, sc, new_value):
    # The task plentifully specifies all choices, including copying the grid.
    # So for each cell the collection of flood candidates expands by adding every
    # adjacent cell whose value is the original one; those are the ones that keep
    # their value V, while the starting cell itself, once visited, switches to the
    # target value T, and copying the result ensures the input stays intact.
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return [row[:] for row in grid]
    result = [row[:] for row in grid]
    result[sr][sc] = new_value
    state = FloodState()
    state.capacity = float('inf')
    for x in range(1, len(grid) + 1):
        for y in range(1, len(grid[0]) + 1):
            state.cells = []
            state.result = [row[:] for row in result]
            search(sr, sc, original, new_value, state, x, y)
            if state.next_cell is not None:
                return state.result
    return result

def search(r, c, original, new_value, state, x, y):
    from itertools import product
    for dr, dc in product([-1, 0, 1], repeat=2):
        if dr == 0 and dc == 0:
            continue
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(state.result) and 0 <= nc < len(state.result[0]):
            candidate = state.result[nr][nc]
            if candidate == original:
                state.cells.append((nr, nc))
                fill(original, new_value, state.result, nr, nc)
    if state.capacity <= len(state.cells):
        for nr, nc in state.cells:
            state.next_cell = (nr, nc)
            fill(original, new_value, state.result, nr, nc)
            return
    # Retry with direction pruning
    for dr, dc in product([-1, 0, 1], repeat=2):
        if dr == 0 and dc == 0:
            continue
        nr, nc = r + dr, c + dc
        if nr == x - 1:
            dr = -dr
        if nc == y - 1:
            dc = -dc
        if 0 <= nr < len(state.result) and 0 <= nc < len(state.result[0]):
            candidate = state.result[nr][nc]
            if candidate == original:
                state.next_cell = (nr, nc)
                fill(original, new_value, state.result, nr, nc)
                return

def fill(original, new_value, grid, r, c):
    if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == original:
